const ATS_ENDPOINTS = {
  greenhouse: 'https://boards-api.greenhouse.io/v1/boards/{slug}/jobs?content=true',
  ashby:      'https://api.ashbyhq.com/posting-api/job-board/{slug}?includeCompensation=true'
};

const rawItems = $input.all();
let notes = [];

// Obsidian /search/ returns [{filename, result}] where result IS the frontmatter object
// (because we used and-returns-last-truthy trick in the JSONLogic query)
if (rawItems.length === 1 && Array.isArray(rawItems[0].json)) {
  notes = rawItems[0].json;
} else {
  notes = rawItems.map(i => i.json);
}

const result = [];
for (const note of notes) {
  // result field contains the frontmatter when using and-returns-last-truthy JSONLogic
  const fm = note.result || note.frontmatter || note;
  const company = (fm.company || '').trim();
  const atsType = (fm.ats_type || '').toLowerCase().trim();
  const boardSlug = (fm.board_slug || '').trim();

  // Only greenhouse and ashby are supported; lever is excluded at query time
  if (!atsType || !['greenhouse', 'ashby'].includes(atsType)) continue;
  if (!boardSlug) continue;

  const urlTemplate = ATS_ENDPOINTS[atsType];
  const url = urlTemplate.replace('{slug}', boardSlug);

  result.push({ json: { company, ats_type: atsType, slug: boardSlug, url } });
}
return result;

const priorityPattern = /\b(priority)\b/i;
const excludeTitlePattern = /marketing manager|brand manager|performance marketing|growth marketing|sales manager|key account|business development|pr manager|communications manager/i;
const requiresHighGermanPattern = /deutsch\s*(c1|c2|muttersprache|muttersprachlich|verhandlungssicher|fließend|fliessend)|german\s*(c1|c2|native|fluent)|native\s*german\s*speaker|fluent\s*in\s*german|muttersprachlich\s*deutsch/i;
const LOCATION_OK = /\b(germany|deutschland|berlin|munich|münchen|hamburg|cologne|köln|frankfurt|düsseldorf|stuttgart|dublin|london|amsterdam|paris|madrid|barcelona|lisbon|stockholm|copenhagen|helsinki|vienna|zurich|warsaw|emea|europe|eu\b|remote)\b/i;
const AMERICAS_ONLY = /\b(americas only|us only|u\.s\. only|us-only|us based|us-based|canada only|latam|apac only|north america only)\b/i;

const today = new Date().toISOString().slice(0, 10);
const items = $input.all();
const buildItems = $('Code: Build ATS requests').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const body = item.json;

  const buildItem = buildItems[i] || null;
  const ats_type = buildItem ? buildItem.json.ats_type : '';
  const companyName = buildItem ? buildItem.json.company : '';

  let jobs = [];

  if (ats_type === 'greenhouse') {
    const raw = body.jobs || [];
    for (const j of raw) {
      const title = j.title || null;
      const location = j.location?.name || '';
      const descRaw = typeof j.content === 'string' ? j.content : null;
      const description = descRaw ? descRaw.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : null;
      const haystack = `${title || ''} ${description || ''} ${location}`;
      jobs.push({
        source: 'greenhouse',
        external_id: j.id ? String(j.id) : null,
        url: j.absolute_url || null,
        title,
        company: companyName,
        location,
        salary: null,
        description,
        priority_bonus: priorityPattern.test(haystack),
        date_seen: today
      });
    }
  } else if (ats_type === 'ashby') {
    const raw = body.jobs || [];
    for (const j of raw) {
      const title = j.title || null;
      const primaryLoc = j.location || '';
      const secondary = Array.isArray(j.secondaryLocations)
        ? j.secondaryLocations.map(s => s.locationName || s.location || '').filter(Boolean).join('; ')
        : '';
      const location = [primaryLoc, secondary].filter(Boolean).join('; ');
      const description = j.descriptionPlain || null;
      const haystack = `${title || ''} ${description || ''} ${location}`;
      jobs.push({
        source: 'ashby',
        external_id: j.id || null,
        url: j.jobUrl || j.applyUrl || null,
        title,
        company: companyName,
        location,
        salary: j.compensation?.compensationTierSummary || null,
        description,
        priority_bonus: priorityPattern.test(haystack),
        date_seen: today
      });
    }
  }

  for (const job of jobs) {
    if (!job.url) continue;
    if (excludeTitlePattern.test(job.title || '')) continue;
    if (job.priority_bonus) { results.push({ json: job }); continue; }
    if (AMERICAS_ONLY.test(job.location || '')) continue;
    if (requiresHighGermanPattern.test(job.description || '')) continue;
    if (LOCATION_OK.test(job.location || '')) results.push({ json: job });
  }
}

return results;
